import React from "react";

const Answer = ({
  question,
  options,
  selectedAnswer,
  correctAnswer,
  hint,
  explanation,
  difficulty,
  subject,
  topic,
}) => {
  return (
    <div className="bg-gradient-to-br from-gray-50 to-white rounded-xl p-8 mb-12 shadow-md max-w-3xl mx-auto border border-gray-200">
      {/* Question */}
      <div className="space-y-3">
        <h3 className="text-2xl font-semibold text-gray-800">
          Question
        </h3>
        <p className="text-gray-600 text-lg">{question}</p>
      </div>

      {/* Options */}
      <div className="mt-6 space-y-3">
        <h4 className="text-xl font-medium text-gray-800">Options</h4>
        <ul className="space-y-3">
          {options?.map((option, index) => (
            <li
              key={index}
              className={`px-5 py-3 rounded-xl cursor-pointer transition duration-300 ease-in-out text-gray-700 text-base font-medium ${
                option === options[selectedAnswer]
                  ? option === correctAnswer
                    ? "bg-gradient-to-br from-green-100 to-green-50 border border-green-300 shadow-sm"
                    : "bg-gradient-to-br from-red-100 to-red-50 border border-red-300 shadow-sm"
                  : option === correctAnswer
                  ? "bg-gradient-to-br from-teal-50 to-white border border-teal-300"
                  : "bg-gray-50 border border-gray-200"
              }`}
            >
              {index + 1}. {option}
            </li>
          ))}
        </ul>
      </div>

      {/* Feedback */}
      {selectedAnswer !== undefined && (
        <div
          className={`mt-6 text-center text-lg font-semibold ${
            options[selectedAnswer] === correctAnswer
              ? "text-green-500"
              : "text-red-500"
          }`}
        >
          {options[selectedAnswer] === correctAnswer
            ? "Great Job! Correct Answer 🎉"
            : "Oops! That’s Incorrect 😞"}
        </div>
      )}

      {/* Hint Section */}
      {hint && (
        <div className="mt-6 p-4 bg-blue-50 border-l-4 border-blue-400 rounded-lg">
          <h4 className="text-lg font-medium text-blue-800">Hint</h4>
          <p className="text-gray-700 mt-2">{hint}</p>
        </div>
      )}

      {/* Explanation Section */}
      {explanation && (
        <div className="mt-6 p-4 bg-yellow-50 border-l-4 border-yellow-400 rounded-lg">
          <h4 className="text-lg font-medium text-yellow-800">Explanation</h4>
          <p className="text-gray-700 mt-2">{explanation}</p>
        </div>
      )}

      {/* Additional Info */}
      <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-6 text-sm text-gray-600">
        <div>
          <span className="block font-medium text-gray-800">Difficulty:</span>
          <span className="capitalize">{difficulty || "Unknown"}</span>
        </div>
        <div>
          <span className="block font-medium text-gray-800">Subject:</span>
          {subject || "N/A"}
        </div>
        <div>
          <span className="block font-medium text-gray-800">Topic:</span>
          {topic || "N/A"}
        </div>
      </div>
    </div>
  );
};

export default Answer;
